  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Rhetoric, Logic and Critical Thinking$j$, $j${"readings": [{"title": "1 Peter 3 (King James Version)", "url": "/portal/bible/1Peter/3"}], "body": "Rhetoric is the art of using words well to inform and persuade. It was studied in ancient Greece and Rome, and the philosopher Aristotle, who lived in the fourth century before Christ, described three appeals that speakers use. 1 Peter 3:15 gives a Christian pattern: But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear. A ready answer given with meekness joins reason and respect.\n\nThe three appeals are ethos, pathos and logos. Ethos is the appeal to the speaker's credibility and character. Listeners trust speakers who are knowledgeable, honest and caring. Pathos is the appeal to emotion. Stories, vivid images and sincere feeling can move people to care. Logos is the appeal to logic and evidence, using facts, statistics and reasoning. A strong speech balances all three. Emotion without facts can mislead, and facts without any feeling can leave an audience unmoved.\n\nGood reasoning moves from evidence to a conclusion. Inductive reasoning moves from specific examples to a general claim, such as, Each of the five hurricanes this year weakened over land, so storms tend to weaken over land. Its conclusion is probable and not certain. Deductive reasoning moves from a general rule to a specific case. If all humans are mortal, and Socrates is a human, then Socrates is mortal. If the starting statements are true and the form is valid, the conclusion must be true. Causal reasoning argues that one thing causes another, and it needs more than two events happening together. Reasoning by analogy compares two similar cases.\n\nA fallacy is an error in reasoning. Learn to spot common ones. An ad hominem attack targets the person instead of the argument. A straw man misstates an opponent's view to make it easy to knock down. A false dilemma claims there are only two choices when there are more. A slippery slope claims, without proof, that one step will lead to disaster. A hasty generalization draws a broad conclusion from too little evidence. A bandwagon appeal says that something is right because many people do it. An appeal to false authority uses an expert in one field to support a claim in another. A red herring distracts with an unrelated point. A post hoc fallacy assumes that because B followed A, A caused B.\n\nCritical thinkers ask for evidence, check sources, look for other explanations and stay open to correction. Isaiah 1:18 says, Come now, and let us reason together, saith the LORD. Faith and reason can walk together.\n\nYour task: (1) Define ethos, pathos and logos with an example of each. (2) Tell the difference between inductive and deductive reasoning. (3) Identify and explain three fallacies.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, 1 Peter 3:15 says, But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear. A ready answer given with meekness joins reason and respect.\n\nNow watch this. Rhetoric is the art of using words well. Aristotle described three appeals. Ethos is the speaker's credibility and character. Pathos is emotion. Logos is logic and evidence. A strong speech balances all three.\n\nInductive reasoning moves from specific examples to a general claim, and its conclusion is probable. Deductive reasoning moves from a general rule to a specific case. If the starting statements are true and the form is valid, the conclusion must be true. Causal reasoning needs more than two events happening together.\n\nA fallacy is an error in reasoning. Ad hominem attacks the person. A straw man misstates a view. A false dilemma offers only two choices. A slippery slope predicts disaster without proof. A hasty generalization uses too little evidence. A bandwagon appeal says many people do it. A red herring distracts. A post hoc fallacy assumes B followed A, so A caused B.\n\nIsaiah 1:18 says, Come now, and let us reason together, saith the LORD.\n\nYour task is to define the appeals, compare reasoning and identify fallacies. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Rhetoric, Logic and Critical Thinking$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Speaking About Faith with Grace$j$, $j${"readings": [{"title": "Colossians 4 (King James Version)", "url": "/portal/bible/Colossians/4"}], "body": "Believers are called to speak about what they know and love, and to do it with wisdom. Colossians 4:6 says, Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man. Grace means kindness and favor, and salt means a clear and wholesome flavor. A believer's speech should be gracious and truthful at once.\n\nThe Bible is full of speaking. Prophets proclaimed God's word. Nehemiah read the law to the people. Jesus taught on hillsides and in homes. Peter spoke at Pentecost, and Paul reasoned in synagogues and in the marketplace. Their speaking was rooted in Scripture, delivered with courage and aimed at the good of the listeners. In every age, God has used human voices to share His truth.\n\nSpeaking about faith begins with a life that matches the words. Listeners notice whether the speaker is humble, kind and consistent. Pray before speaking, and ask God for wisdom and love. Know the Scripture you quote and read it in its context, so you do not twist a verse to say something it does not say. Use the King James Version accurately, citing book, chapter and verse. Explain unfamiliar words, since many young listeners do not know terms such as redemption or righteousness. Use stories and clear examples, as Jesus did.\n\nShare a testimony with honesty. A testimony is a true account of what God has done in your life. Keep it brief, specific and centered on Christ and not on yourself. Avoid saying more about other people than they would want said, and do not describe sin in graphic detail.\n\nSpeak with respect. People have different beliefs and backgrounds. Listen to their questions, answer clearly and do not mock. Avoid arguments for the sake of winning. 2 Timothy 2:24 says, And the servant of the Lord must not strive; but be gentle unto all men, apt to teach, patient. Be prepared for hard questions and be honest when you do not know. It is better to say, I will study that and get back to you, than to guess.\n\nIn a school, workplace or public setting, know the rules. Public school and workplace settings have guidelines about religious speech, and church and ministry settings have their own. A wise speaker follows the rules, respects the setting and looks for appropriate openings, such as conversations with friends, service projects and youth ministry. Always have a parent or pastor in the loop when you are younger.\n\nYour task: (1) Explain what it means for speech to be seasoned with salt. (2) List five principles for speaking about faith. (3) Outline a one minute testimony.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Colossians 4:6 says, Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man. Grace is kindness, and salt is a clear and wholesome flavor. A believer's speech should be gracious and truthful at once.\n\nNow watch this. The Bible is full of speaking. Prophets proclaimed. Nehemiah read the law. Jesus taught. Peter spoke at Pentecost. Paul reasoned in synagogues and in the marketplace. God has used human voices in every age.\n\nSpeaking about faith begins with a life that matches your words. Pray before speaking. Know the Scripture in its context and cite it accurately. Explain unfamiliar words. Use stories as Jesus did.\n\nA testimony is a true account of what God has done in your life. Keep it brief, specific and centered on Christ. Do not say more about others than they would want said.\n\nSpeak with respect. Listen to questions. Do not mock. Do not argue to win. 2 Timothy 2:24 says, And the servant of the Lord must not strive; but be gentle unto all men, apt to teach, patient. When you do not know, say, I will study that and get back to you.\n\nKnow the rules of the setting. Keep a parent or pastor in the loop.\n\nYour task is to explain salt, list principles and outline a testimony. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Speaking About Faith with Grace$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Public Leadership and Community Speaking$j$, $j${"readings": [{"title": "Nehemiah 2 (King James Version)", "url": "/portal/bible/Nehemiah/2"}], "body": "Leaders must speak. They cast a vision, rally a team, report on progress and encourage people in hard times. Nehemiah is a model. When he saw the broken wall of Jerusalem, he spoke to the people. Nehemiah 2:17 and 18 records, Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach. And they said, Let us rise up and build. So they strengthened their hands for this good work.\n\nNotice how Nehemiah spoke. He named a shared problem, ye see the distress that we are in. He included himself, saying us and we. He gave a clear goal, build up the wall. He offered hope, and he gave an invitation to act. Leaders who speak this way unite people around a purpose.\n\nA leader's speech should have a clear message, a reason, a plan and a call to action. Keep it short and plain. Say what matters most first. Use stories and examples that people recognize. Speak with honesty when the news is hard, and with gratitude when the work is good. Thank people by name and give credit to those who earned it. A leader who takes the credit loses trust.\n\nCommunity speaking happens in many places. A student might speak at a school board meeting, a city commission hearing, a neighborhood association or a church business meeting. In such meetings, there are usually rules for public comment, such as signing up in advance and speaking for three minutes. Prepare a short statement, state your name and your concern, give one or two strong facts and make a specific request. Be courteous even when you disagree. Thank the board for listening. Written statements, letters to officials and petitions are also forms of civic speech. In Florida and across the United States, citizens have a right to petition and speak to their government, and using this right wisely is a form of service.\n\nCrisis communication also calls for care. In a hurricane, an emergency or a time of grief, leaders should speak calmly, tell the truth, give clear instructions and show care. They should not guess or spread rumors. Short, steady, kind messages, repeated through reliable channels, help communities.\n\nYour task: (1) List four elements of Nehemiah's speech in Nehemiah 2. (2) Outline a two minute public comment for a community meeting. (3) Describe three principles for speaking in a crisis.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Nehemiah 2:17 and 18 say, Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach. And they said, Let us rise up and build. So they strengthened their hands for this good work.\n\nNow watch this. Nehemiah named a shared problem. He included himself with us and we. He gave a clear goal. He offered hope. He gave an invitation to act.\n\nA leader's speech has a clear message, a reason, a plan and a call to action. Keep it short and plain. Say what matters most first. Be honest when news is hard. Thank people by name. A leader who takes the credit loses trust.\n\nCommunity speaking happens at school boards, city meetings and church business meetings. Sign up in advance, prepare a short statement, state your name and concern, give one or two strong facts, make a specific request and be courteous. Letters and petitions are civic speech too. Citizens have the right to petition their government.\n\nIn a crisis, speak calmly, tell the truth, give clear instructions, show care and do not spread rumors.\n\nYour task is to list Nehemiah's elements, outline a public comment and describe crisis speaking. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Public Leadership and Community Speaking$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Evaluating Speeches, Your Portfolio and Your Calling$j$, $j${"readings": [{"title": "Psalm 19 (King James Version)", "url": "/portal/bible/Psalms/19"}], "body": "To grow as a speaker, you must learn to evaluate speeches, both others' and your own. Psalm 19:14 is a prayer every speaker can make: Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer.\n\nEvaluation begins with clear criteria. Ask about content. Was the topic clear and the purpose met? Was the evidence accurate and cited? Ask about organization. Did the speech have a strong introduction, a clear body and a conclusion that finished well? Ask about delivery. Was the voice clear, varied and the right volume? Did the speaker use eye contact, good posture and natural gestures? Did the speaker stay within the time? Ask about language. Were the words clear, correct and appropriate? Ask about audience connection. Did the speaker adapt to the listeners and show respect? Ask about ethics. Was the speaker honest and fair?\n\nGood feedback is specific, kind and helpful. A useful method is to give two strengths and one suggestion for growth. Say, Your opening story grabbed my attention. Your three points were easy to follow. Next time try to look up from your notes more. Avoid vague remarks such as, It was good, or harsh remarks that attack the person. When you receive feedback, listen without arguing, thank the person and choose one or two changes to try. Proverbs 27:17 says, Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.\n\nSelf evaluation uses a recording. Watch or listen to your speech once for content, then again for delivery. Note the times you looked at your notes, the filler words, the pace and the pauses. Write a short reflection about what went well, what to change and what you learned.\n\nA speaking portfolio is a collection of your best work. It might include outlines, a recording or video of a speech, written feedback, a reflection and a list of speaking experiences, such as class talks, devotionals, youth day presentations and service projects. A portfolio shows growth, and it can support a college application, a scholarship or a job.\n\nCommunication skills open many callings: teaching, ministry, business, law, healthcare, media, public service and more. 1 Corinthians 10:31 says, Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God. Use your voice to serve others, tell the truth in love and give God the glory.\n\nYour task: (1) List five criteria for evaluating a speech. (2) Give feedback to a speaker using two strengths and one suggestion. (3) Describe what you would include in a speaking portfolio.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Psalm 19:14 says, Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer. That is a prayer every speaker can make.\n\nNow watch this. To grow, evaluate speeches with clear criteria. Content. Organization. Delivery. Language. Audience connection. Ethics.\n\nGood feedback is specific, kind and helpful. Give two strengths and one suggestion. Say, your opening story grabbed my attention, your three points were easy to follow, next time try to look up from your notes more. When you receive feedback, listen, thank the person and choose one or two changes. Proverbs 27:17 says, Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.\n\nFor self evaluation, record your speech. Watch once for content and again for delivery. Note filler words, pace and pauses. Write a reflection.\n\nA speaking portfolio holds your best work: outlines, a recording, feedback, a reflection and a list of speaking experiences. It shows growth and can support a college application, a scholarship or a job.\n\nCommunication opens callings in teaching, ministry, business, law, healthcare, media and public service. 1 Corinthians 10:31 says, whatsoever ye do, do all to the glory of God.\n\nYour task is to list criteria, give feedback and describe a portfolio. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Evaluating Speeches, Your Portfolio and Your Calling$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Speaking with Purpose, Faith and Leadership$j$, $j${"prompt": "Write a report of at least 250 words on rhetoric, faith, leadership and evaluation. Use complete sentences and label each part. Psalm 19:14 says, Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer.\n\nPart 1: Define ethos, pathos and logos and give an example of each from a speech or sermon. Explain the difference between inductive and deductive reasoning, and identify and explain four fallacies with an example of each.\nPart 2: Explain what it means for speech to be seasoned with salt, list five principles for speaking about faith, and outline a one minute testimony that is honest, brief and centered on Christ.\nPart 3: Explain the elements of Nehemiah's speech in Nehemiah 2:17 and 18. Outline a two minute public comment on a school or community issue.\nPart 4: List criteria for evaluating a speech. Evaluate a speech you have heard (a recorded speech, a sermon or a school talk) by giving two strengths and one suggestion.\nPart 5: Describe what you would put in a speaking portfolio and name one calling in which communication skills will matter. Apply 1 Peter 3:15 and 1 Corinthians 10:31.", "rubric": "100 points. Part 1: 25 points. Part 2: 20 points. Part 3: 15 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Speaking with Purpose, Faith and Leadership$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Let Your Speech Be Seasoned with Grace$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a leader, teacher or speaker who spoke with both truth and grace, (2) explains in your own words one way to tell good reasoning from a fallacy, (3) explains how you can use your voice to serve your family, church or community, and (4) connects your answer to Colossians 4:6, 1 Peter 3:15, Nehemiah 2:17 or Psalm 19:14. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a believer speak the truth in love in a world that disagrees? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Let Your Speech Be Seasoned with Grace$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Rhetoric, Logic and Critical Thinking$j$, $j${"questions": [{"q": "The appeal to a speaker's credibility and character is:", "options": ["Pathos", "Ethos", "Logos", "Kairos"]}, {"q": "The appeal to logic and evidence is:", "options": ["Ethos", "Pathos", "Irony", "Logos"]}, {"q": "Attacking the person instead of the argument is called:", "options": ["A red herring", "Ad hominem", "A straw man", "A bandwagon appeal"]}, {"q": "Moving from a general rule to a specific case is:", "options": ["Deductive reasoning", "Inductive reasoning", "A false dilemma", "Paraphrasing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Rhetoric, Logic and Critical Thinking$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,0}'::int[], array[$j$Ethos is credibility.$j$,$j$Logos relies on reason and facts.$j$,$j$Ad hominem means to the person.$j$,$j$Deduction starts from a general statement.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Rhetoric, Logic and Critical Thinking$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Speaking About Faith with Grace$j$, $j${"questions": [{"q": "Colossians 4:6 says speech should be:", "options": ["Always with grace, seasoned with salt", "Full of arguments", "Loud and angry", "Hidden"]}, {"q": "A testimony is:", "options": ["A debate", "A lecture about others", "A true account of what God has done in your life", "A made up story"]}, {"q": "When a listener asks a question you cannot answer, you should:", "options": ["Mock the question", "Change the subject angrily", "Say you will study it and get back to them", "Guess confidently"]}, {"q": "According to 2 Timothy 2:24, the servant of the Lord must be:", "options": ["Proud", "Quarrelsome", "Silent always", "Gentle, apt to teach and patient"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Speaking About Faith with Grace$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,3}'::int[], array[$j$Gracious and wholesome speech serves listeners.$j$,$j$A testimony is honest and personal.$j$,$j$Honesty and humility build trust.$j$,$j$The servant does not strive.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Speaking About Faith with Grace$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Public Leadership and Community Speaking$j$, $j${"questions": [{"q": "In Nehemiah 2:17, Nehemiah showed leadership by:", "options": ["Naming a shared problem and inviting action", "Staying silent", "Leaving the city", "Blaming the people"]}, {"q": "A good public comment at a community meeting includes:", "options": ["No request", "A long insult", "A rumor", "Your name, your concern, a few facts and a specific request"]}, {"q": "In a crisis, leaders should:", "options": ["Hide information", "Speak calmly, tell the truth and give clear instructions", "Guess", "Spread rumors"]}, {"q": "A leader who takes all the credit:", "options": ["Becomes humble", "Loses trust", "Gains trust", "Improves the team"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Public Leadership and Community Speaking$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,1}'::int[], array[$j$He united the people around a purpose.$j$,$j$Short, clear and courteous statements are most effective.$j$,$j$Calm and honest messages help communities.$j$,$j$Giving credit builds trust.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Public Leadership and Community Speaking$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Evaluating Speeches, Your Portfolio and Your Calling$j$, $j${"questions": [{"q": "A helpful way to give feedback is to give:", "options": ["Only praise", "Two strengths and one suggestion", "Vague remarks", "Only criticism"]}, {"q": "A collection of your best speaking work, with feedback and reflection, is a:", "options": ["Motion", "Speaking portfolio", "Fallacy", "Transition"]}, {"q": "Which is a criterion for evaluating a speech?", "options": ["Room temperature", "Hair color", "The color of the podium", "Organization"]}, {"q": "Proverbs 27:17 compares feedback among friends to:", "options": ["Smoke", "Wind", "Sand", "Iron sharpening iron"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Evaluating Speeches, Your Portfolio and Your Calling$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,3}'::int[], array[$j$Balanced and specific feedback helps growth.$j$,$j$A portfolio shows growth.$j$,$j$Organization is part of the content and structure.$j$,$j$Friends sharpen one another.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Evaluating Speeches, Your Portfolio and Your Calling$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Speaking with Purpose, Faith and Leadership$j$, $j${"questions": [{"q": "An argument that uses facts, statistics and reasoning is using:", "options": ["Ethos", "Pathos", "Logos", "Humor only"]}, {"q": "A claim that there are only two choices when there are more is a:", "options": ["Post hoc", "Hasty generalization", "False dilemma", "Red herring"]}, {"q": "Misstating an opponent's view to make it easy to defeat is a:", "options": ["Slippery slope", "Straw man", "Syllogism", "Bandwagon"]}, {"q": "Speech seasoned with salt is:", "options": ["Bitter", "Careless", "Clear, wholesome and gracious", "Silent"]}, {"q": "A testimony should be:", "options": ["Long and about others", "Honest, brief and centered on Christ", "A debate", "Made up"]}, {"q": "Nehemiah inspired the people by:", "options": ["Blaming them", "Giving orders without reasons", "Leaving", "Naming a shared problem and inviting action"]}, {"q": "A good way to give feedback is:", "options": ["Only a score", "Silence", "Two strengths and one suggestion", "Only criticism"]}, {"q": "1 Corinthians 10:31 teaches that we should do all things:", "options": ["To the glory of God", "For ourselves only", "For fame", "In secret"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Speaking with Purpose, Faith and Leadership$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,2,1,3,2,0}'::int[], array[$j$Logos is the appeal to logic.$j$,$j$It limits the options unfairly.$j$,$j$A straw man attacks a weak copy of the argument.$j$,$j$Salt adds a clear and wholesome flavor.$j$,$j$A testimony tells what God has done.$j$,$j$He used we and us and a clear goal.$j$,$j$Specific and kind feedback helps a speaker grow.$j$,$j$Our speech and work give glory to God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Speaking with Purpose, Faith and Leadership$j$ on conflict (item_id) do nothing;
